qualityGateCraftIntegration.auditSnippet:
try {
  const craftFindings = auditCraft(rel, content, projectRoot);
  const craftErrors = craftFindings.filter(f => f.severity === "error");
  const craftAdvice = craftFindings.filter(f => f.severity === "advice");
  if (craftErrors.length > 0) warnings.push(...formatCraftWarnings(craftErrors));
  if (craftAdvice.length > 0) process.stderr.write(formatCraftWarnings(craftAdvice).join("\n") + "\n");
} catch {}

sessionStartCharterInjection.snippet:
const charterPath = path.join(projectRoot, "docs", "craft", "charter.md");
if (fs.existsSync(charterPath)) {
  try {
    const ch = fs.readFileSync(charterPath, "utf8");
    summary += `\nCraft Charter:\n${ch}\n`;
  } catch {}
}
